package servers_test

// L756F2 (THROWAWAY ab/l756f2-diag-20261116, not for merge): the registry columns of the REGRESSION GUARDS of the RULE 74 A/B of the #756 fix candidate (celeris PR #1306, default loop reserve n/8 -> n/4) against
// FINAL main (servers/l756f2_arms.go, generated by l756f2-gen.py). The expectations are stated here, not derived from the code under test; the two pins come from servers/celeris/go.mod and servers/celeris_pr1306/go.mod
// (the byte-copy test of the L756F head, TestL756FFixModuleIsAByteCopyOfTheMainAdapter, covers that A and B differ by the celeris pin only).

import (
	"regexp"
	"sort"
	"strings"
	"testing"

	"github.com/goceleris/probatorium/servers"
)

var l756f2Name = regexp.MustCompile(`^l756f2-([0-9]{3})-r([1-3])-(a|a2|b)-(epoll-h1-async|epoll-h1-sync|iouring-h1-sync|adaptive-h1-async)$`)

func TestL756F2Columns(t *testing.T) {
	var cols []servers.Adapter
	for n, a := range servers.Registry {
		if strings.HasPrefix(n, "l756f2-") {
			cols = append(cols, a)
		}
	}
	sort.Slice(cols, func(i, j int) bool { return cols[i].Name < cols[j].Name })
	if len(cols) != 36 {
		t.Fatalf("%d l756f2 columns, want 36 (3 reps x 4 engines x 3 arms)", len(cols))
	}
	mainPin, fixPin := l756fPin(t, "celeris"), l756fPin(t, "celeris_pr1306")
	if mainPin == fixPin {
		t.Fatalf("servers/celeris and servers/celeris_pr1306 pin the same celeris %s: there is no A/B", mainPin)
	}
	perRepEngine := map[string]map[string]int{}
	for i, a := range cols {
		mm := l756f2Name.FindStringSubmatch(a.Name)
		if mm == nil {
			t.Fatalf("column name %q", a.Name)
		}
		seq, rep, arm, eng := mm[1], mm[2], mm[3], mm[4]
		if want := i + 1; seq != strings.Repeat("0", 3-len(l756fItoa(want)))+l756fItoa(want) {
			t.Errorf("%s: seq %s is not the sorted position %d", a.Name, seq, want)
		}
		key := rep + "/" + eng
		if perRepEngine[key] == nil {
			perRepEngine[key] = map[string]int{}
		}
		perRepEngine[key][arm]++
		base := servers.Registry["celeris-"+eng]
		if a.Engine != eng || a.Engine != base.Engine || a.Capabilities != base.Capabilities || a.Category != base.Category || a.Language != base.Language {
			t.Errorf("%s: engine / capabilities differ from its base column", a.Name)
		}
		wantMod, wantPin := "servers/celeris", mainPin
		if arm == "b" {
			wantMod, wantPin = "servers/celeris_pr1306", fixPin
		}
		if a.Framework != "celeris-l756f2-"+arm || a.FrameworkVersion != wantPin {
			t.Errorf("%s: framework %s version %s, want celeris-l756f2-%s / %s", a.Name, a.Framework, a.FrameworkVersion, arm, wantPin)
		}
		if gb, ok := a.Bin.(servers.GoBinary); !ok || gb.ModuleDir != wantMod {
			t.Errorf("%s: bin %#v, want module %s", a.Name, a.Bin, wantMod)
		}
		// NO knob, sampler or GOGC env: the genuine default of each module (the registry base column's own env, if any, is kept unchanged).
		if len(a.SUTEnv) != len(base.SUTEnv) {
			t.Errorf("%s: SUTEnv %v differs from its base column %v", a.Name, a.SUTEnv, base.SUTEnv)
		}
		for k, v := range a.SUTEnv {
			if base.SUTEnv[k] != v || k == "GOGC" || k == "GOMAXPROCS" || strings.HasPrefix(k, "PROBATORIUM_") {
				t.Errorf("%s: SUTEnv[%s] = %q is not in the base column", a.Name, k, v)
			}
		}
		if len(a.RatedPlans) != len(base.RatedPlans) || a.Baseline {
			t.Errorf("%s: rated plans %#v / Baseline %v differ from the base column (the guards run saturation passes only)", a.Name, a.RatedPlans, a.Baseline)
		}
	}
	if len(perRepEngine) != 12 {
		t.Errorf("%d (rep, engine) groups, want 12", len(perRepEngine))
	}
	for key, arms := range perRepEngine {
		if len(arms) != 3 {
			t.Errorf("%s has %d arms, want 3", key, len(arms))
		}
		for arm, n := range arms {
			if n != 1 {
				t.Errorf("%s arm %s %d times", key, arm, n)
			}
		}
	}
}
